-- Atualizar usuários sem student_id com IDs sequenciais
SET @counter = (SELECT COALESCE(MAX(CAST(SUBSTRING(student_id, 10) AS UNSIGNED)), 0) FROM users WHERE student_id LIKE 'INF-2026-%');

UPDATE users 
SET student_id = CONCAT('INF-2026-', LPAD(@counter := @counter + 1, 4, '0'))
WHERE student_id IS NULL OR student_id = '';

